// Analizar respuesta del API
const response = $input.first().json;

// Extraer información de la respuesta
const status = response.status;
const client = response.client;
const meta = response.meta || {};
const data = response.data || [];

// Información de paginación
const paginacion = {
  pagina_actual: meta.current_page || 1,
  por_pagina: meta.per_page || 100,
  total_registros: meta.total_records || 0,
  total_paginas: meta.total_pages || 1,
  periodo: meta.period || {}
};

// Analizar estructura de las detecciones
let estructuraDeteccion = null;
let ejemploDeteccion = null;

if (data.length > 0) {
  ejemploDeteccion = data[0];
  estructuraDeteccion = {
    campos: Object.keys(ejemploDeteccion),
    tipos: {}
  };

  // Determinar tipos de datos
  Object.keys(ejemploDeteccion).forEach(key => {
    const valor = ejemploDeteccion[key];
    estructuraDeteccion.tipos[key] = typeof valor;
  });
}

// Agrupar por campos clave para análisis
const agrupaciones = {
  por_canal: {},
  por_spot: {},
  por_ciudad: {},
  por_fecha: {}
};

data.forEach(d => {
  // Por canal
  const canal = d.channel_name || 'Sin canal';
  agrupaciones.por_canal[canal] = (agrupaciones.por_canal[canal] || 0) + 1;

  // Por spot
  const spot = d.spot_name || 'Sin spot';
  agrupaciones.por_spot[spot] = (agrupaciones.por_spot[spot] || 0) + 1;

  // Por ciudad
  const ciudad = d.city || 'Sin ciudad';
  agrupaciones.por_ciudad[ciudad] = (agrupaciones.por_ciudad[ciudad] || 0) + 1;

  // Por fecha (parsear formato RFC 2822: "Mon, 12 Jan 2026 23:56:06 GMT")
  if (d.datetime_utc) {
    try {
      const fechaObj = new Date(d.datetime_utc);
      if (!isNaN(fechaObj.getTime())) {
        const año = fechaObj.getFullYear();
        const mes = String(fechaObj.getMonth() + 1).padStart(2, '0');
        const dia = String(fechaObj.getDate()).padStart(2, '0');
        const fecha = `${año}-${mes}-${dia}`;
        agrupaciones.por_fecha[fecha] = (agrupaciones.por_fecha[fecha] || 0) + 1;
      }
    } catch (e) {
      // Si falla el parseo, usar string vacío
      agrupaciones.por_fecha[''] = (agrupaciones.por_fecha[''] || 0) + 1;
    }
  }
});

return [{
  json: {
    // Información general
    status: status,
    client: client,

    // Paginación
    paginacion: paginacion,

    // Estructura de datos
    total_detecciones_recibidas: data.length,
    estructura_deteccion: estructuraDeteccion,
    ejemplo_deteccion: ejemploDeteccion,

    // Agrupaciones para análisis
    agrupaciones: agrupaciones,

    // Respuesta completa (para inspección)
    respuesta_completa: response,

    // Resumen
    resumen: {
      mensaje: `API respondió con status: ${status}`,
      total_registros: paginacion.total_registros,
      registros_en_pagina: data.length,
      tiene_mas_paginas: paginacion.pagina_actual < paginacion.total_paginas,
      campos_por_deteccion: estructuraDeteccion ? estructuraDeteccion.campos.length : 0
    }
  }
}];
